package io.ochre.bridge;
import java.util.*;
import static io.ochre.bridge.ActionSupport.*;

/// Public, read-only snapshots; field names are fixed by the bridge rather than supplied by a script.
final class ObservationSnapshots {
 private ObservationSnapshots() { }
 static Map<String,String> screen(Object c)throws Exception{Object s=InputActions.screen(c);return Map.of("open",Boolean.toString(s!=null),"type",s==null?"none":s.getClass().getSimpleName(),"identity",s==null?"none":Integer.toString(System.identityHashCode(s)),"paused",call(c,"isPaused").toString(),"in_world",Boolean.toString(field(c,"player")!=null));}
 static Map<String,String> vitals(Object c)throws Exception{Object p=player(c),food=call(p,"getFoodData");Map<String,String> v=new LinkedHashMap<>();for(var e:Map.ofEntries(Map.entry("health","getHealth"),Map.entry("max_health","getMaxHealth"),Map.entry("absorption","getAbsorptionAmount"),Map.entry("armor","getArmorValue"),Map.entry("air","getAirSupply"),Map.entry("alive","isAlive"),Map.entry("on_fire","isOnFire"),Map.entry("in_water","isInWater"),Map.entry("in_lava","isInLava"),Map.entry("freezing","isFreezing"),Map.entry("frozen_ticks","getTicksFrozen"),Map.entry("passenger","isPassenger"),Map.entry("using_item","isUsingItem"),Map.entry("use_ticks","getUseItemRemainingTicks")).entrySet())v.put(e.getKey(),call(p,e.getValue()).toString());v.put("fall_distance",field(p,"fallDistance").toString());v.put("food",call(food,"getFoodLevel").toString());v.put("saturation",call(food,"getSaturationLevel").toString());v.put("xp_level",field(p,"experienceLevel").toString());v.put("xp_progress",field(p,"experienceProgress").toString());Object stack=call(p,"getUseItem");v.put("using_item_id",Boolean.TRUE.equals(call(stack,"isEmpty"))?"minecraft:air":id(call(stack,"getItem")));v.put("use_animation",call(stack,"getUseAnimation").toString().toLowerCase(Locale.ROOT));return Map.copyOf(v);}
 static Map<String,String> container(Object c)throws Exception{Object p=player(c),menu=field(p,"containerMenu");boolean open=menu!=field(p,"inventoryMenu");return Map.of("open",Boolean.toString(open),"id",field(menu,"containerId").toString(),"type",menu.getClass().getSimpleName(),"identity",Integer.toString(System.identityHashCode(menu)),"token",ContainerActions.token(c,menu),"slot_count",Integer.toString(((List<?>)field(menu,"slots")).size()));}
 static void append(Map<String,String> target,String prefix,Map<String,String> fields){fields.forEach((key,value)->target.put(prefix+key,value));}
 static void inspect(Object c,Map<String,String> request,Map<String,String> response)throws Exception{Map<String,String> data=switch(request.getOrDefault("kind","")){case "screen"->screen(c);case "vitals"->vitals(c);case "container"->container(c);case "status"->Map.of("hooks",String.join(",",new TreeSet<>(OverlayTransformer.observations)),"sampling_hz","10","retained_events","256","event_page","64");default->throw new java.io.IOException("observation.kind.invalid");};response.putAll(data);}
}
